package br.com.trama.controller;
import br.com.trama.dto.*; import br.com.trama.security.UsuarioPrincipal; import br.com.trama.service.CotacaoCorporativaService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.responses.ApiResponse; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/cotacoes") @Tag(name="Cotações corporativas",description="Solicitações de cotação feitas por empresários") public class CotacaoCorporativaController {private final CotacaoCorporativaService service;public CotacaoCorporativaController(CotacaoCorporativaService s){service=s;} @PostMapping @Operation(summary="Criar cotação corporativa",description="Recebe produtos e prazo, registra a solicitação e cria notificações para os artesãos vinculados.") @SecurityRequirement(name="bearerAuth") @ApiResponse(responseCode="201",description="Cotação criada e artesãos notificados") @ApiResponse(responseCode="400",description="Dados inválidos") @ApiResponse(responseCode="403",description="Perfil sem permissão") public ResponseEntity<CotacaoResponse> criar(@Valid @RequestBody CotacaoRequest req,@AuthenticationPrincipal UsuarioPrincipal principal){CotacaoResponse r=service.criar(req,principal);URI uri=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(r.id()).toUri();return ResponseEntity.created(uri).body(r);}}
